import React, { useState, useEffect, useContext } from 'react';
import { useHistory } from 'react-router-dom';
import { CartContext } from '../../context/CartContext';
import Header from '../../components/client/Header';
import Footer from '../../components/client/Footer';
import '../../styles/home.css';

function Checkout() {
    const { cartItems, setCartItems } = useContext(CartContext);
    const history = useHistory();
    const userId = localStorage.getItem('userId');

    const [formData, setFormData] = useState({
        address: '',
        postalCode: '',
        city: '',
        country: '',
        paymentPreference: 'Carte bancaire'
    });
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (!userId) {
            // User is not logged in, just stop loading and let them fill the form
            setLoading(false);
            return;
        }
        
        fetch(`http://localhost:3001/user/${userId}`)
            .then(res => res.json())
            .then(data => {
                setFormData({
                    address: data.address || '',
                    postalCode: data.postalCode || '',
                    city: data.city || '',
                    country: data.country || '',
                    paymentPreference: data.paymentPreference || 'Carte bancaire'
                });
                setLoading(false);
            })
            .catch(err => {
                console.error('Erreur lors de la récupération des informations utilisateur', err);
                setLoading(false);
            });
    }, [userId]);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handlePayment = (e) => {
        e.preventDefault();
        
        if (!userId) {
            alert('Vous devez être connecté pour passer une commande.');
            history.push('/login');
            return;
        }

        const orderData = {
            idUser: userId,
            cartItems: cartItems
        };

        fetch('http://localhost:3001/order', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(orderData)
        })
        .then(res => {
            if (!res.ok) {
                throw new Error('Erreur lors de la création de la commande');
            }
            return res.json();
        })
        .then(data => {
            alert('Paiement validé avec succès ! Merci pour votre achat.');
            setCartItems([]); // Empty the cart
            history.push('/orders'); // Redirect to My Orders
        })
        .catch(err => {
            console.error(err);
            alert('Une erreur est survenue lors de la validation de la commande.');
        });
    };

    const total = cartItems.reduce((acc, item) => acc + item.price * item.quantity, 0);

    if (loading) {
        return <div style={{ textAlign: 'center', marginTop: '50px' }}>Chargement de vos informations...</div>;
    }

    return (
        <div className="home">
            <Header />
            <div className="container" style={{ display: 'block', maxWidth: '600px', margin: '40px auto', minHeight: '60vh', padding: '20px', backgroundColor: '#f9f9f9', borderRadius: '8px' }}>
                <h1 style={{ marginBottom: '20px', textAlign: 'center' }}>Paiement</h1>
                
                <div style={{ marginBottom: '30px', padding: '15px', backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #ddd' }}>
                    <h3>Résumé de la commande</h3>
                    <p>Nombre d'articles : {cartItems.length}</p>
                    <p style={{ fontSize: '18px', fontWeight: 'bold' }}>Total à payer : {total.toFixed(2)} €</p>
                </div>

                <form onSubmit={handlePayment} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                        <label style={{ marginBottom: '5px', fontWeight: 'bold' }}>Adresse de livraison :</label>
                        <input 
                            type="text" 
                            name="address" 
                            value={formData.address} 
                            onChange={handleInputChange} 
                            required 
                            style={{ padding: '10px', borderRadius: '4px', border: '1px solid #ccc' }}
                        />
                    </div>
                    
                    <div style={{ display: 'flex', gap: '15px' }}>
                        <div style={{ display: 'flex', flexDirection: 'column', flex: 1 }}>
                            <label style={{ marginBottom: '5px', fontWeight: 'bold' }}>Code postal :</label>
                            <input 
                                type="text" 
                                name="postalCode" 
                                value={formData.postalCode} 
                                onChange={handleInputChange} 
                                required 
                                style={{ padding: '10px', borderRadius: '4px', border: '1px solid #ccc' }}
                            />
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', flex: 1 }}>
                            <label style={{ marginBottom: '5px', fontWeight: 'bold' }}>Ville :</label>
                            <input 
                                type="text" 
                                name="city" 
                                value={formData.city} 
                                onChange={handleInputChange} 
                                required 
                                style={{ padding: '10px', borderRadius: '4px', border: '1px solid #ccc' }}
                            />
                        </div>
                    </div>

                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                        <label style={{ marginBottom: '5px', fontWeight: 'bold' }}>Pays :</label>
                        <input 
                            type="text" 
                            name="country" 
                            value={formData.country} 
                            onChange={handleInputChange} 
                            required 
                            style={{ padding: '10px', borderRadius: '4px', border: '1px solid #ccc' }}
                        />
                    </div>

                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                        <label style={{ marginBottom: '5px', fontWeight: 'bold' }}>Méthode de paiement :</label>
                        <select 
                            name="paymentPreference" 
                            value={formData.paymentPreference} 
                            onChange={handleInputChange} 
                            required
                            style={{ padding: '10px', borderRadius: '4px', border: '1px solid #ccc' }}
                        >
                            <option value="Carte bancaire">Carte bancaire</option>
                            <option value="Paypal">Paypal</option>
                            <option value="Virement">Virement</option>
                        </select>
                    </div>

                    <button 
                        type="submit" 
                        style={{ backgroundColor: '#28a745', color: 'white', border: 'none', padding: '15px', fontSize: '18px', borderRadius: '4px', cursor: 'pointer', marginTop: '20px' }}
                    >
                        Valider et Payer
                    </button>
                </form>
            </div>
            <Footer />
        </div>
    );
}

export default Checkout;
